class Solution {
  public long weightedSum(int[] parent, int[] nums) {
    int n = parent.length;
    int[] head = new int[n], next = new int[n];
    java.util.Arrays.fill(head, -1);
    for (int i = 1; i < n; i++) {
      next[i] = head[parent[i]];
      head[parent[i]] = i;
    }
    int[] depth = new int[n], queue = new int[n];
    int qh = 0, qt = 0, height = 1;
    queue[qt++] = 0;
    depth[0] = 1;
    while (qh < qt) {
      int u = queue[qh++];
      height = Math.max(height, depth[u]);
      for (int c = head[u]; c >= 0; c = next[c]) {
        depth[c] = depth[u] + 1;
        queue[qt++] = c;
      }
    }
    long total = 0;
    for (int i = 0; i < n; i++) total += (long) nums[i] * (height - depth[i] + 1);
    return total;
  }
}
